            # use stores present in both years
            k6=set(D[p+'26']);k5=set(D[p+'25']); common=[k for k in k6 & k5 if (ks is None or k in ks)]
            a,ua,n=tot(D,p+'26',common); b,ub,_=tot(D,p+'25',common)
            print(f"{p:5}{nm:8} n={n:2} venta {a/1e6:6.1f} vs {b/1e6:6.1f} {g(a,b):6.1f}% | uni {ua:5.0f} vs {ub:5.0f} {g(ua,ub):6.1f}% | p/u c/IVA {a/ua*1.19:7,.0f} vs {b/ub*1.19:7,.0f} {g(a/ua,b/ub):6.1f}%")
